t.script:
/* global document */
(function () {
    'use strict';

    var frame = document.getElementById('external_livechat_frame');
    if (!frame) { return; }

    var iframeDoc = null;

    /*
     * Detecta si las coordenadas del cursor caen sobre un elemento
     * del widget de livechat usando elementFromPoint() sobre el
     * documento del iframe.
     *
     * Ventaja sobre getBoundingClientRect(): funciona aunque el
     * contenedor raíz del widget tenga dimensiones 0×0 (caso común
     * cuando Odoo usa position:fixed en hijos, no en el padre).
     * elementFromPoint() consulta qué elemento está renderizado
     * visualmente en ese píxel, independientemente del tamaño del
     * contenedor o de los cambios de estado del chat.
     *
     * Como el iframe está fijo en top:0 left:0 cubriendo el 100%
     * de la ventana, las coordenadas viewport del parent coinciden
     * exactamente con las del iframe.
     */
    function isOverLivechat(cx, cy) {
        if (!iframeDoc) { return false; }
        try {
            var el = iframeDoc.elementFromPoint(cx, cy);
            /* Sin elemento o solo el fondo del iframe → no es el widget */
            if (!el
                || el === iframeDoc.documentElement
                || el === iframeDoc.body) {
                return false;
            }
            /*
             * Recorremos el árbol hacia arriba buscando cualquier
             * elemento cuya clase o id contenga "livechat".
             * Esto cubre: botón minimizado, panel abierto, overlays
             * internos y cualquier sub-componente del widget.
             */
            var node = el;
            while (node && node.nodeType === 1 && node !== iframeDoc.body) {
                var cls = typeof node.className === 'string' ? node.className : '';
                var id  = node.id || '';
                if (
                    cls.toLowerCase().indexOf('livechat') !== -1 ||
                    id.toLowerCase().indexOf('livechat')  !== -1
                ) {
                    return true;
                }
                node = node.parentElement;
            }
        } catch (e) { /* seguridad cross-origin inesperada → ignorar */ }
        return false;
    }

    /*
     * En cada movimiento del mouse en Odoo 18 toggleamos
     * pointer-events del iframe:
     *   - sobre el widget → auto  (eventos llegan al iframe/chat)
     *   - fuera del widget → none (eventos llegan a Odoo 18)
     *
     * Nota: los eventos dentro del iframe no burbujean al parent,
     * pero sí lo hace el mousemove sobre el elemento <iframe> en
     * sí, por lo que este handler se dispara en todos los casos.
     */
    document.addEventListener('mousemove', function (e) {
        if (!iframeDoc) { return; }
        frame.style.pointerEvents = isOverLivechat(e.clientX, e.clientY)
            ? 'auto'
            : 'none';
    });

    frame.addEventListener('load', function () {
        try {
            iframeDoc = (
                frame.contentDocument ||
                (frame.contentWindow && frame.contentWindow.document)
            );
            if (iframeDoc) {
                // Escuchar mousemove dentro del iframe para liberar
                // pointer-events cuando el cursor ya no está sobre el
                // widget. Sin esto, una vez que pointer-events pasa a
                // "auto", el handler del parent deja de dispararse
                // y el iframe bloquea toda la página.
                iframeDoc.addEventListener('mousemove', function (e) {
                    if (!isOverLivechat(e.clientX, e.clientY)) {
                        frame.style.pointerEvents = 'none';
                    }
                });
            }
        } catch (e) {
            console.warn('[ExternalLivechat] No se pudo acceder al DOM del iframe:', e);
        }
    });
})();
